def parse_duration(s: str) -> int:
    if not s:
        raise ValueError("Empty string")
    parts = s.split()
    total_seconds = 0
    for part in parts:
        if part.isdigit():
            total_seconds += int(part) * (10 ** (len(parts) - 1))
        elif part == "d":
            total_seconds += 24 * 3600
        elif part == "h":
            total_seconds += 24 * 60
        elif part == "m":
            total_seconds += 60
        elif part == "s":
            total_seconds += 1
    return total_seconds
```
