def binary_search(nums: list[int], target: int) -> int:
    # Check if the list is empty
    if not nums:
        return -1

    # Find the middle index of the list
    mid = len(nums) // 2

    # If the target integer is less than the middle index, search the lower half
    if target < nums[mid]:
        return binary_search(nums[:mid], target)

    # If the target integer is greater than the middle index, search the upper half
    else:
        return binary_search(nums[mid+1:], target)

Final answer: -1
```
